-- Additive compatibility patch for existing local databases after commit 107e825.
-- Keep existing data and EF history unchanged; do not run the full Min migration over an existing schema.
BEGIN;
SET LOCAL search_path TO public;
SET LOCAL lock_timeout = '5s';

CREATE TABLE IF NOT EXISTS tour_versions (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TourId" integer NOT NULL,
    "VersionNo" integer NOT NULL,
    "Title" character varying(200) NOT NULL,
    "Description" character varying(4000) NOT NULL,
    "EstimatedMinutes" integer NOT NULL,
    "Status" character varying(20) NOT NULL,
    "PublicAt" timestamp with time zone,
    "CreatedBy" uuid NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "SubmittedBy" uuid,
    "SubmittedAt" timestamp with time zone,
    "ReviewedBy" uuid,
    "ReviewedAt" timestamp with time zone,
    "ReviewNote" character varying(1000),
    CONSTRAINT "PK_tour_versions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_tour_versions_Users_CreatedBy" FOREIGN KEY ("CreatedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_tour_versions_Users_ReviewedBy" FOREIGN KEY ("ReviewedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_tour_versions_Users_SubmittedBy" FOREIGN KEY ("SubmittedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_tour_versions_tours_TourId" FOREIGN KEY ("TourId") REFERENCES tours ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS tour_version_items (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TourVersionId" integer NOT NULL,
    "ArtifactId" integer NOT NULL,
    "OrderNo" integer NOT NULL,
    CONSTRAINT "PK_tour_version_items" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_tour_version_items_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_tour_version_items_tour_versions_TourVersionId" FOREIGN KEY ("TourVersionId") REFERENCES tour_versions ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS saved_routes (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VisitorId" uuid NOT NULL,
    "MuseumId" integer NOT NULL,
    "TourId" integer NOT NULL,
    "TourVersionId" integer NOT NULL,
    "TopicIdsJson" character varying(1000) NOT NULL,
    "AvailableMinutes" integer NOT NULL,
    "Score" double precision NOT NULL,
    "Explanation" character varying(1000) NOT NULL,
    "SavedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_saved_routes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_saved_routes_Users_VisitorId" FOREIGN KEY ("VisitorId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_saved_routes_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_saved_routes_tour_versions_TourVersionId" FOREIGN KEY ("TourVersionId") REFERENCES tour_versions ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_saved_routes_tours_TourId" FOREIGN KEY ("TourId") REFERENCES tours ("Id") ON DELETE RESTRICT
);

ALTER TABLE visits ADD COLUMN IF NOT EXISTS "TourVersionId" integer;

ALTER TABLE visit_items ADD COLUMN IF NOT EXISTS "TourVersionItemId" integer;

CREATE INDEX IF NOT EXISTS "IX_saved_routes_MuseumId" ON saved_routes ("MuseumId");

CREATE INDEX IF NOT EXISTS "IX_saved_routes_TourId" ON saved_routes ("TourId");

CREATE INDEX IF NOT EXISTS "IX_saved_routes_TourVersionId" ON saved_routes ("TourVersionId");

CREATE INDEX IF NOT EXISTS "IX_saved_routes_VisitorId_MuseumId_SavedAt" ON saved_routes ("VisitorId", "MuseumId", "SavedAt");

CREATE INDEX IF NOT EXISTS "IX_tour_version_items_ArtifactId" ON tour_version_items ("ArtifactId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_tour_version_items_TourVersionId_ArtifactId" ON tour_version_items ("TourVersionId", "ArtifactId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_tour_version_items_TourVersionId_OrderNo" ON tour_version_items ("TourVersionId", "OrderNo");

CREATE INDEX IF NOT EXISTS "IX_tour_versions_CreatedBy" ON tour_versions ("CreatedBy");

CREATE INDEX IF NOT EXISTS "IX_tour_versions_ReviewedBy" ON tour_versions ("ReviewedBy");

CREATE INDEX IF NOT EXISTS "IX_tour_versions_SubmittedBy" ON tour_versions ("SubmittedBy");

CREATE INDEX IF NOT EXISTS "IX_tour_versions_TourId_Status_PublicAt" ON tour_versions ("TourId", "Status", "PublicAt");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_tour_versions_TourId_VersionNo" ON tour_versions ("TourId", "VersionNo");

CREATE INDEX IF NOT EXISTS "IX_visit_items_TourVersionItemId" ON visit_items ("TourVersionItemId");

CREATE INDEX IF NOT EXISTS "IX_visits_TourVersionId" ON visits ("TourVersionId");

DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_visits_tour_versions_TourVersionId' AND conrelid = 'visits'::regclass) THEN
  ALTER TABLE visits ADD CONSTRAINT "FK_visits_tour_versions_TourVersionId" FOREIGN KEY ("TourVersionId") REFERENCES tour_versions ("Id") ON DELETE RESTRICT;
 END IF;
END $$;

DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_visit_items_tour_version_items_TourVersionItemId' AND conrelid = 'visit_items'::regclass) THEN
  ALTER TABLE visit_items ADD CONSTRAINT "FK_visit_items_tour_version_items_TourVersionItemId" FOREIGN KEY ("TourVersionItemId") REFERENCES tour_version_items ("Id") ON DELETE RESTRICT;
 END IF;
END $$;

COMMIT;
